steps.solution:
def parse(line):
    raw = line.split(",")
    parts = [p.strip() for p in raw]
    if len(parts) != 3 or "" in parts:
        return None
    return {"tag": parts[0].upper(),
            "item": parts[1].lower(),
            "room": parts[2].upper()}

